    # Plateau definitions
    def is_western_plateau(px, py):
        return 15 <= px <= 22 and 20 <= py <= 27

    def is_eastern_plateau(px, py):
        return 27 <= px <= 38 and 12 <= py <= 23

    # Check start and target elevations
    start_on_west_plat = is_western_plateau(start_x, start_y)
