    # Multi-elevation pathfinding using (x, y, elevation) state
    # elevation = 0 (ground), 1 (plateau)
    start_el = 1 if (start_on_west_plat or start_on_east_plat) else 0
    target_el = 1 if (target_on_west_plat or target_on_east_plat) else 0

