                            valid_move = True
                        elif (nx, ny) == (34, 15) or (nx, ny) == (28, 27):
                            valid_move = True

                if valid_move and (nx, ny, nel) not in visited:
                    visited.add((nx, ny, nel))
                    queue.append((nx, ny, nel, path + [move]))

    print(json.dumps(path_found))
